// Canvas-2D renderer. Every pixel of the board is drawn from primitives — one lamp per bit,
// and a press lights exactly the cross that js/core/grid.js describes. The two bitmap assets
// under art/ (a grain texture and a spark sprite) are decoration only: they are generated by
// art/gen/gen_art.py from the same palette and the same geometry constants used here, and if
// either one fails to load the picture is still drawn from primitives. Semantics never come
// from an image — the lit/unlit state is read from `cells`, so a missing asset can only make
// the board prettier or plainer, never wrong.
//
// The geometry is part of the public surface, and it is all in one space: CSS pixels *inside
// the canvas box* (origin = the canvas's own top-left, which is what `clientWidth` measures).
// main.js turns a pointerdown into a cell by subtracting getBoundingClientRect() first, and
// tools/playtest.mjs turns a cell index into a click by adding it back — "press cell 7" is then
// the same click for a finger, for a route change, and for a Chrome DevTools Protocol event.
//
// Time comes in from the outside only: js/clock.js owns the rAF loop and hands every frame a
// dt and a stamp. Nothing here calls performance.now(), because a renderer that reads the wall
// clock behind the harness's back cannot be tested for frame-rate independence at all.

const TAU = Math.PI * 2;
const PULSE_SECONDS = 0.5;
// 粒子物理走定步长：30/60/120Hz 下每步的 s 恒等于 SIM_STEP，所以轨迹逐帧一致。
const SIM_STEP = 1 / 120;
const SPARK_LIFE = 0.45;

const PALETTE = {
  floor: '#0e1118',
  plate: '#151a23',
  plateEdge: 'rgba(226, 232, 240, 0.10)',
  wire: 'rgba(226, 232, 240, 0.06)',
  lampOn: '#ffd35c',
  lampOnCore: '#fff6d8',
  lampOff: '#232a36',
  lampOffCore: '#2c3542',
  halo: 'rgba(255, 211, 92, 0.28)',
  ink: '#e6e9ef',
  dim: '#8b95a7',
  answer: '#78dcff',
  good: '#6ee7b7',
};

export function createView(canvas, { reduceMotion } = {}) {
  const ctx = canvas.getContext('2d');
  let n = 4;
  let cells = new Array(16).fill(0);
  let answer = new Set();
  let held = new Set();
  let showAnswer = false;
  let solved = false;
  let paused = false;
  let pulse = new Map();
  let particles = [];
  let simAccumulator = 0;
  let simSteps = 0;
  let lastStamp = 1000;
  let dirty = true;
  const motionReduced = reduceMotion === undefined
    ? (typeof matchMedia === 'function' && matchMedia('(prefers-reduced-motion: reduce)').matches)
    : !!reduceMotion;
  let grainPattern = null;
  let sparkImage = null;

  // 两张位图都是"能拿到就用"：node 测试环境、file:// 下被 CORS 拒、或者用户离线且没缓存到，
  // 都不该让画面少一块语义。onerror 只记一次状态，供 debug() 报告。
  const assets = { grain: 'pending', spark: 'pending' };
  function loadAssets() {
    if (typeof Image !== 'function' || typeof document === 'undefined') {
      assets.grain = 'skipped';
      assets.spark = 'skipped';
      return;
    }
    const grain = new Image();
    grain.onload = () => {
      try {
        const pat = ctx.createPattern(grain, 'repeat');
        if (pat) grainPattern = pat;
        assets.grain = 'ready';
      } catch (err) {
        assets.grain = 'rejected';
      }
      dirty = true;
    };
    grain.onerror = () => { assets.grain = 'missing'; };
    grain.src = 'art/textures/plate-grain-256.png';
    const spark = new Image();
    spark.onload = () => { sparkImage = spark; assets.spark = 'ready'; };
    spark.onerror = () => { assets.spark = 'missing'; };
    spark.src = 'art/sprites/spark-64.png';
  }

  // ---- geometry ------------------------------------------------------------

  function metrics() {
    const w = canvas.clientWidth || canvas.width || 320;
    const h = canvas.clientHeight || canvas.height || 320;
    const size = Math.max(120, Math.min(w, h));
    const pad = Math.round(size * 0.055);
    const gap = Math.max(3, Math.round(size * 0.016));
    const cell = (size - pad * 2 - gap * (n - 1)) / n;
    return {
      w, h, size, pad, gap, cell,
      extent: n * cell + (n - 1) * gap,
      left: (w - size) / 2 + pad,
      top: (h - size) / 2 + pad,
    };
  }

  function cellRect(i) {
    const m = metrics();
    const r = Math.floor(i / n);
    const c = i % n;
    return {
      i,
      r,
      c,
      x: m.left + c * (m.cell + m.gap),
      y: m.top + r * (m.cell + m.gap),
      s: m.cell,
    };
  }

  function cellCenter(i) {
    const q = cellRect(i);
    return { x: q.x + q.s / 2, y: q.y + q.s / 2 };
  }

  // Which lamp owns this point? Canvas-box CSS pixels, same space as cellRect/cellCenter.
  // -1 for the gaps and the margin: a click between two lamps presses nothing, which is what
  // main.js and the @pointer assertions both assume.
  function cellAt(x, y) {
    const m = metrics();
    if (x < m.left || y < m.top || x > m.left + m.extent || y > m.top + m.extent) return -1;
    const c = Math.floor((x - m.left) / (m.cell + m.gap));
    const r = Math.floor((y - m.top) / (m.cell + m.gap));
    if (c < 0 || r < 0 || c >= n || r >= n) return -1;
    const q = cellRect(r * n + c);
    if (x < q.x || x > q.x + q.s || y < q.y || y > q.y + q.s) return -1;
    return r * n + c;
  }

  // ---- drawing -------------------------------------------------------------

  function roundRect(x, y, w, h, r) {
    const rad = Math.max(0, Math.min(r, w / 2, h / 2));
    ctx.beginPath();
    ctx.moveTo(x + rad, y);
    ctx.arcTo(x + w, y, x + w, y + h, rad);
    ctx.arcTo(x + w, y + h, x, y + h, rad);
    ctx.arcTo(x, y + h, x, y, rad);
    ctx.arcTo(x, y, x + w, y, rad);
    ctx.closePath();
  }

  function drawRoom(m) {
    const g = ctx.createLinearGradient(0, 0, 0, m.h);
    g.addColorStop(0, '#12151d');
    g.addColorStop(1, PALETTE.floor);
    ctx.fillStyle = g;
    ctx.fillRect(0, 0, m.w, m.h);

    // 磨砂纹理铺在房间里：alpha 压到 6%，读成"暗房的颗粒"而不是图案。拿不到位图就整段跳过。
    if (grainPattern) {
      ctx.save();
      ctx.globalAlpha = 0.06;
      ctx.fillStyle = grainPattern;
      ctx.fillRect(0, 0, m.w, m.h);
      ctx.restore();
    }

    // The plate the switches sit on, plus the wires that tie neighbours together — the visual
    // statement of "pressing here also flips there".
    const x = m.left - m.pad;
    const y = m.top - m.pad;
    const side = m.extent + m.pad * 2;
    ctx.save();
    ctx.fillStyle = PALETTE.plate;
    ctx.strokeStyle = PALETTE.plateEdge;
    ctx.lineWidth = 1;
    roundRect(x + 0.5, y + 0.5, side - 1, side - 1, 18);
    ctx.fill();
    ctx.stroke();
    ctx.restore();

    ctx.save();
    ctx.strokeStyle = PALETTE.wire;
    ctx.lineWidth = 1;
    for (let i = 0; i < n * n; i++) {
      const a = cellCenter(i);
      if (i % n + 1 < n) {
        const b = cellCenter(i + 1);
        ctx.beginPath();
        ctx.moveTo(a.x + 2, a.y);
        ctx.lineTo(b.x - 2, b.y);
        ctx.stroke();
      }
      if (Math.floor(i / n) + 1 < n) {
        const b = cellCenter(i + n);
        ctx.beginPath();
        ctx.moveTo(a.x, a.y + 2);
        ctx.lineTo(b.x, b.y - 2);
        ctx.stroke();
      }
    }
    ctx.restore();
  }

  function drawLamp(i, now) {
    const q = cellRect(i);
    const lit = !!cells[i];
    const r = motionReduced ? 0 : pulse.get(i) || 0;
    const age = r ? (now - r) / 1000 : 1;
    const flash = age < PULSE_SECONDS ? 1 - age / PULSE_SECONDS : 0;
    const inset = q.s * 0.1;
    const box = { x: q.x + inset, y: q.y + inset, s: q.s - inset * 2 };

    if (lit) {
      const glow = q.s * (0.5 + flash * 0.22);
      const halo = ctx.createRadialGradient(
        box.x + box.s / 2, box.y + box.s / 2, box.s * 0.15,
        box.x + box.s / 2, box.y + box.s / 2, glow
      );
      halo.addColorStop(0, PALETTE.halo);
      halo.addColorStop(1, 'rgba(255, 211, 92, 0)');
      ctx.fillStyle = halo;
      ctx.fillRect(q.x - glow / 2, q.y - glow / 2, q.s + glow, q.s + glow);
    }

    ctx.save();
    roundRect(box.x, box.y, box.s, box.s, box.s * 0.26);
    const face = ctx.createLinearGradient(box.x, box.y, box.x, box.y + box.s);
    if (lit) {
      face.addColorStop(0, PALETTE.lampOnCore);
      face.addColorStop(0.45, PALETTE.lampOn);
      face.addColorStop(1, '#c9932a');
    } else {
      face.addColorStop(0, PALETTE.lampOffCore);
      face.addColorStop(1, PALETTE.lampOff);
    }
    ctx.fillStyle = face;
    ctx.fill();
    ctx.lineWidth = 1;
    ctx.strokeStyle = lit ? 'rgba(255, 246, 216, 0.55)' : 'rgba(226, 232, 240, 0.08)';
    ctx.stroke();
    ctx.restore();

    // A filament in the middle: the lamp reads as a lamp even in a greyscale screenshot.
    ctx.save();
    ctx.beginPath();
    ctx.arc(box.x + box.s / 2, box.y + box.s / 2, box.s * (lit ? 0.16 : 0.1), 0, TAU);
    ctx.fillStyle = lit ? 'rgba(255, 255, 255, 0.9)' : 'rgba(226, 232, 240, 0.12)';
    ctx.fill();
    ctx.restore();

    if (flash > 0) {
      ctx.save();
      ctx.globalAlpha = flash * 0.8;
      ctx.strokeStyle = lit ? PALETTE.lampOnCore : PALETTE.dim;
      ctx.lineWidth = 2;
      roundRect(q.x, q.y, q.s, q.s, q.s * 0.28);
      ctx.stroke();
      ctx.restore();
    }

    if (held.has(i)) {
      // Four corner ticks: "this switch is held". Pressing it again takes them away, which is
      // the same parity fact the maths rests on.
      ctx.save();
      ctx.strokeStyle = PALETTE.ink;
      ctx.lineWidth = 2;
      const t = box.s * 0.22;
      const corners = [
        [box.x, box.y, 1, 1], [box.x + box.s, box.y, -1, 1],
        [box.x, box.y + box.s, 1, -1], [box.x + box.s, box.y + box.s, -1, -1],
      ];
      for (const [cx, cy, sx, sy] of corners) {
        ctx.beginPath();
        ctx.moveTo(cx, cy + sy * t);
        ctx.lineTo(cx, cy);
        ctx.lineTo(cx + sx * t, cy);
        ctx.stroke();
      }
      ctx.restore();
    }

    if (showAnswer && answer.has(i)) {
      ctx.save();
      ctx.strokeStyle = solved ? PALETTE.good : PALETTE.answer;
      ctx.lineWidth = 2;
      ctx.setLineDash([4, 3]);
      roundRect(box.x + 2, box.y + 2, box.s - 4, box.s - 4, box.s * 0.22);
      ctx.stroke();
      ctx.setLineDash([]);
      ctx.beginPath();
      ctx.arc(box.x + box.s / 2, box.y + box.s / 2, box.s * 0.06, 0, TAU);
      ctx.fillStyle = solved ? PALETTE.good : PALETTE.answer;
      ctx.fill();
      ctx.restore();
    }
  }

  function drawSparks() {
    if (motionReduced || !particles.length) return;
    ctx.save();
    for (const p of particles) {
      const k = Math.max(0, p.life / SPARK_LIFE);
      const size = p.r * (0.6 + 0.4 * k) * 2;
      ctx.globalAlpha = k * k;
      if (sparkImage) {
        ctx.drawImage(sparkImage, p.x - size / 2, p.y - size / 2, size, size);
      } else {
        ctx.fillStyle = p.warm ? PALETTE.lampOn : PALETTE.answer;
        ctx.beginPath();
        ctx.arc(p.x, p.y, size / 2, 0, TAU);
        ctx.fill();
      }
    }
    ctx.restore();
  }

  function drawPauseVeil(m) {
    ctx.save();
    ctx.fillStyle = 'rgba(8, 10, 14, 0.72)';
    ctx.fillRect(0, 0, m.w, m.h);
    ctx.strokeStyle = 'rgba(255, 211, 92, 0.5)';
    ctx.lineWidth = 2;
    const cx = m.w / 2;
    const cy = m.h / 2;
    const bar = Math.max(10, m.size * 0.045);
    ctx.beginPath();
    ctx.rect(cx - bar * 1.6, cy - bar, bar * 0.9, bar * 2);
    ctx.rect(cx + bar * 0.7, cy - bar, bar * 0.9, bar * 2);
    ctx.stroke();
    ctx.fillStyle = PALETTE.ink;
    ctx.font = `${Math.round(m.size * 0.05)}px "SF Mono", Menlo, monospace`;
    ctx.textAlign = 'center';
    ctx.fillText('已暂停 · 按 P 继续', cx, cy + bar * 2.6);
    ctx.restore();
  }

  function drawFrame(now) {
    const m = metrics();
    drawRoom(m);
    for (let i = 0; i < n * n; i++) drawLamp(i, now);
    drawSparks();
    if (paused) drawPauseVeil(m);
  }

  // Anything still moving? The pulse and the sparks are the only two things that are, and the
  // clock uses this to decide whether to keep scheduling frames at all.
  function busy() {
    if (motionReduced) return false;
    if (particles.length) return true;
    for (const t of pulse.values()) if ((lastStamp - t) / 1000 < PULSE_SECONDS) return true;
    return false;
  }

  function needsFrame() {
    return dirty || busy();
  }

  // 只负责把背板像素数对上 CSS 尺寸，然后标脏。它自己不排帧：帧循环是 js/clock.js 的，
  // main.js 在 resize 之后会调 clock.invalidate() 把它叫醒。
  function resize() {
    const dpr = Math.max(1, Math.min(3, (typeof devicePixelRatio === 'number' ? devicePixelRatio : 1) || 1));
    const w = canvas.clientWidth || 320;
    const h = canvas.clientHeight || 320;
    const wantW = Math.round(w * dpr);
    const wantH = Math.round(h * dpr);
    if (canvas.width !== wantW || canvas.height !== wantH) {
      canvas.width = wantW;
      canvas.height = wantH;
    }
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    dirty = true;
  }

  // 定步长推进粒子。注意 `simAccumulator += dt` 这一行吃的是帧 dt，它是本仓唯一
  // 一处"帧率必须无关"的积分点，也是帧率对拍时阴性对照要钉的那一行。
  function simulate(dt) {
    simAccumulator += dt;
    let guard = 0;
    while (simAccumulator >= SIM_STEP && guard++ < 600) {
      simAccumulator -= SIM_STEP;
      simSteps += 1;
      const next = [];
      for (const p of particles) {
        p.life -= SIM_STEP;
        if (p.life <= 0) continue;
        const drag = Math.pow(0.22, SIM_STEP);
        p.vx *= drag;
        p.vy *= drag;
        p.vy += p.buoyancy * SIM_STEP;
        p.x += p.vx * SIM_STEP;
        p.y += p.vy * SIM_STEP;
        next.push(p);
      }
      particles = next;
    }
    if (guard >= 600) simAccumulator = 0;
  }

  function decayPulses() {
    if (!pulse.size) return;
    for (const [i, t] of pulse) if ((lastStamp - t) / 1000 >= PULSE_SECONDS) pulse.delete(i);
  }

  return {
    setBoard(next) {
      if (next.n && next.n !== n) {
        n = next.n;
        pulse = new Map();
        particles = [];
        simAccumulator = 0;
      }
      if (next.cells) cells = next.cells.slice();
      if (next.answer) answer = new Set(next.answer);
      if (next.pressed) held = new Set(next.pressed.map((v, i) => (v ? i : -1)).filter((i) => i >= 0));
      if (typeof next.showAnswer === 'boolean') showAnswer = next.showAnswer;
      if (typeof next.solved === 'boolean') solved = next.solved;
      dirty = true;
    },
    setPaused(next) {
      paused = !!next;
      dirty = true;
    },
    // The whole simulation reset for a new attempt: the clock, the buffers, the particles and
    // the transient pulses. Leaving any of them behind is how "重开" ends up showing last
    // attempt's sparks and last attempt's remaining glow.
    resetFx() {
      particles = [];
      pulse = new Map();
      simAccumulator = 0;
      simSteps = 0;
      dirty = true;
    },
    // Which lamps just changed, and the sparks that fly off them. Decoration only: the lit/unlit
    // state itself is drawn from `cells`, so a player with reduced motion still sees the true board.
    flash(indices, stamp) {
      if (motionReduced || !indices || !indices.length) return;
      const now = stamp || lastStamp;
      const m = metrics();
      for (const i of indices) {
        pulse.set(i, now);
        const c = cellCenter(i);
        const count = 3;
        for (let k = 0; k < count; k++) {
          const ang = (k / count) * TAU + (i % n) * 0.4;
          const speed = m.cell * (1.2 + 0.5 * ((i + k) % 3));
          particles.push({
            x: c.x, y: c.y,
            vx: Math.cos(ang) * speed, vy: Math.sin(ang) * speed,
            life: SPARK_LIFE, r: m.cell * 0.09,
            buoyancy: -m.cell * 0.6,
            warm: !!cells[i],
          });
        }
      }
      dirty = true;
    },
    // The one entry point of the frame loop: dt from js/clock.js, 0 while paused.
    step(dt, stamp) {
      lastStamp = typeof stamp === 'number' ? stamp : lastStamp;
      if (dt > 0) simulate(dt);
      decayPulses();
      if (needsFrame()) {
        drawFrame(lastStamp);
        dirty = false;
      }
    },
    busy: () => needsFrame(),
    resize,
    cellRect,
    cellCenter,
    cellAt,
    start() {
      resize();
      loadAssets();
      dirty = true;
    },
    stop() {
      dirty = false;
    },
    // Exposed for the shell, the browser test and the frame-rate harness alike.
    layout() {
      const m = metrics();
      return {
        n,
        width: m.w,
        height: m.h,
        size: m.size,
        pad: m.pad,
        gap: m.gap,
        cell: m.cell,
        extent: m.extent,
        left: m.left,
        top: m.top,
        dpr: (typeof devicePixelRatio === 'number' && devicePixelRatio) || 1,
      };
    },
    debug() {
      // 帧率对拍要比的是"同一虚拟时长之后，粒子在哪里"，只报个数看不出位置错开，
      // 所以这里给出位置/速度/寿命的总和与余晖时间戳的总和。
      const spark = { x: 0, y: 0, life: 0, vx: 0, vy: 0 };
      for (const p of particles) {
        spark.x += p.x;
        spark.y += p.y;
        spark.life += p.life;
        spark.vx += p.vx;
        spark.vy += p.vy;
      }
      let pulseSum = 0;
      for (const t of pulse.values()) pulseSum += t;
      return {
        motionReduced,
        paused,
        particles: particles.length,
        pulses: pulse.size,
        spark,
        pulseSum,
        simSteps,
        simAccumulator,
        assets: { ...assets },
      };
    },
  };
}
